#include <iostream>
#include <string>

int main() {
    std::string anterior;
    std::string actual;
    int posicion{0};
    int repeticiones{0};
    while (std::cin >> actual) {
        ++posicion;
        if (actual == anterior) {
            ++repeticiones;
            std::cout << "Repeated: " << posicion << '\n';
        }
        anterior = actual;
    }
    std::cout << "Words: " << posicion
              << "\nRepetitions: " << repeticiones << '\n';
    return 0;
}

